      coupon: toFiniteNumber(profile.coupon != null ? profile.coupon : (profile.ticket != null ? profile.ticket : profile.pointCoupon)),
      diamond: toFiniteNumber(profile.diamond != null ? profile.diamond : profile.rechargeDiamond),
