    const keys = safeCall(function () { return Object.keys(value).slice(0, 20); }, []);
    if (level >= 4) return { type: 'object', keys: keys };
    const summarized = {};
    keys.forEach(function (key) {
      const cur = safeReadKey(value, key);
      if (typeof cur === 'function' || typeof cur === 'symbol') return;
      summarized[key] = summarizeSvipRewardsStatusValue(cur, level + 1, nextSeen);
    });
