  async function autoFillFertilizerBuckets(opts) {
    opts = opts || {};
    const net = getNetWebSocket();
    if (!net || typeof net.sendMsg !== 'function') throw new Error('netWebSocket.sendMsg not found');
    const fillNormal = opts.fillNormal !== false;
    const fillOrganic = opts.fillOrganic !== false;
    const waitAfterSend = Math.max(0, Number(opts.waitAfterSend == null ? 800 : opts.waitAfterSend) || 0);
    const wasOpen = !!(findWarehousePopupRoot() && findWarehousePopupRoot().activeInHierarchy);
    const closeAfter = opts.forceCloseAfter === true || (opts.closeAfter !== false && !wasOpen);
    const payload = {
      ok: false,
      success: false,
      action: 'auto_fill_fertilizer_buckets',
      executionSource: opts.dryRun === true ? 'direct_protocol_dry_run' : 'direct_protocol_dispatch',
      methodName: 'BatchUse',
      serviceName: 'gamepb.itempb.ItemService',
      wasOpen: wasOpen,
      closeAfter: closeAfter,
      snapshot: null,
      normal: null,
      organic: null,
      dispatches: [],
      totalEntryCount: 0,
      totalFilledCount: 0
    };

    const snapshot = await refreshWarehouseSnapshot({
      silent: true,
      closeAfter: false,
      limit: opts.limit,
      waitAfterOpen: opts.waitAfterOpen,
      waitAfterSwitch: opts.waitAfterSwitch,
      visitAllTabs: opts.visitAllTabs !== false,
      allowEmpty: true
    });
    payload.snapshot = {
      ok: snapshot && snapshot.ok === true,
      itemCount: Number(snapshot && snapshot.itemCount) || 0,
      tabs: snapshot && Array.isArray(snapshot.tabs) ? snapshot.tabs : [],
      reason: snapshot && snapshot.reason || null
    };
    if (!snapshot || snapshot.ok !== true) {
      payload.reason = snapshot && snapshot.reason || 'warehouse_snapshot_failed';
      if (closeAfter) {
        payload.closeResult = await closeWarehouseUi({
          timeoutMs: opts.closeTimeoutMs == null ? 1800 : opts.closeTimeoutMs,
          pollMs: opts.pollMs
        });
      }
      return opts.silent ? payload : out(payload);
    }

    const plan = buildFertilizerFillPlan(snapshot.items);
    payload.plan = plan;
    const groups = [];
    if (fillNormal) groups.push(plan.normal);
    if (fillOrganic) groups.push(plan.organic);
    const requestedEntryCount = groups.reduce(function (sum, group) {
      return sum + (group && Array.isArray(group.entries) ? group.entries.length : 0);
    }, 0);
    if (requestedEntryCount <= 0) {
      payload.ok = true;
      payload.success = true;
      payload.skipped = true;
      payload.reason = 'no_fertilizer_to_fill';
      payload.totalEntryCount = plan.totalEntryCount;
      payload.totalFilledCount = 0;
      if (closeAfter) {
        payload.closeResult = await closeWarehouseUi({
          timeoutMs: opts.closeTimeoutMs == null ? 1800 : opts.closeTimeoutMs,
          pollMs: opts.pollMs
        });
      }
      return opts.silent ? payload : out(payload);
    }

    for (let i = 0; i < groups.length; i += 1) {
      const group = groups[i];
      if (!group || !Array.isArray(group.entries) || group.entries.length <= 0) continue;
      const dispatch = await dispatchFertilizerFillBatch(net, group, opts);
      payload.dispatches.push(dispatch);
      if (group.type === 'normal') payload.normal = dispatch;
      if (group.type === 'organic') payload.organic = dispatch;
      if (waitAfterSend > 0 && i < groups.length - 1) await wait(waitAfterSend);
    }

    payload.totalEntryCount = payload.dispatches.reduce(function (sum, item) {
      return sum + (Number(item && item.entryCount) || 0);
    }, 0);
    payload.totalFilledCount = payload.dispatches.reduce(function (sum, item) {
      return sum + (item && item.ok === true ? (Number(item.filledCount) || 0) : 0);
    }, 0);
    payload.ok = payload.dispatches.length > 0 && payload.dispatches.every(function (item) { return item && item.ok === true; });
    payload.success = payload.ok;
    if (!payload.ok) payload.reason = 'fertilizer_fill_dispatch_failed';
    if (waitAfterSend > 0 && payload.dispatches.length > 0) await wait(waitAfterSend);

    if (closeAfter) {
      payload.closeResult = await closeWarehouseUi({
        timeoutMs: opts.closeTimeoutMs == null ? 1800 : opts.closeTimeoutMs,
        pollMs: opts.pollMs
      });
    }
    return opts.silent ? payload : out(payload);
  }

